const CMS_PAGE_DOCUMENT_VERSION=2;

function cms_page_uuid(): string { return bin2hex(random_bytes(16)); }
function cms_page_slug(string $value): string {
    $value=trim($value);
    if($value==='')return '';
    return activity_slug($value);
}
function cms_sanitize_html(string $html): string {
    if(trim($html)==='')return '';
    $previous=libxml_use_internal_errors(true);
    $dom=new DOMDocument('1.0','UTF-8');
    $wrapped='<!doctype html><html><body><div id="cms-root">'.$html.'</div></body></html>';
    $dom->loadHTML('<?xml encoding="utf-8" ?>'.$wrapped,LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);
    $xpath=new DOMXPath($dom);
    foreach(['script','iframe','object','embed','base','meta','link'] as $tag){foreach(iterator_to_array($xpath->query('//'.$tag)?:[]) as $node)$node->parentNode?->removeChild($node);}
    foreach(iterator_to_array($xpath->query('//*')?:[]) as $element){
        if(!$element instanceof DOMElement)continue;
        for($i=$element->attributes->length-1;$i>=0;$i--){$attr=$element->attributes->item($i);if(!$attr)continue;$name=strtolower($attr->name);$value=trim($attr->value);if(str_starts_with($name,'on')){$element->removeAttributeNode($attr);continue;}if(in_array($name,['href','src','action'],true)&&preg_match('~^\s*(?:javascript|data:text/html)\s*:~i',$value)){$element->removeAttributeNode($attr);}}
    }
    $root=$dom->getElementById('cms-root');$out='';if($root)foreach(iterator_to_array($root->childNodes) as $child)$out.=$dom->saveHTML($child);
    libxml_clear_errors();libxml_use_internal_errors($previous);return $out;
}
function cms_page_document(array $document): array {
    $theme=in_array($document['theme']??'auto',['auto','light','dark'],true)?$document['theme']:'auto';
    $meta=is_array($document['meta']??null)?$document['meta']:[];
    return [
        'version'=>CMS_PAGE_DOCUMENT_VERSION,
        'theme'=>$theme,
        'meta'=>[
            'title'=>trim((string)($meta['title']??'')),
            'description'=>trim((string)($meta['description']??'')),
        ],
        'html'=>cms_sanitize_html((string)($document['html']??'')),
    ];
}
