function cms_pages_seed(PDO $db,int $activityId): void {
    $q=$db->prepare("SELECT COUNT(*) FROM cms_pages WHERE activity_id=? AND status!='archived'");$q->execute([$activityId]);if((int)$q->fetchColumn()>0)return;
    cms_forms_seed($db,$activityId);$now=utc_now();$insert=$db->prepare('INSERT INTO cms_pages(page_uuid,activity_id,locale,slug,title,nav_title,status,is_home,show_in_nav,sort_order,draft_document_json,published_document_json,draft_revision,published_revision,draft_updated_at,published_at,created_at,updated_at)VALUES(?,?,?,?,?,?,"active",1,1,1,?,?,1,1,?,?,?,?)');
    foreach([[PUBLIC_LOCALE_PT_BR,'Positivo Direto em Filme de Raios X','Workshop'],[PUBLIC_LOCALE_EN,'Direct Positive X-Ray Film','Workshop']] as [$locale,$title,$nav]){$doc=cms_default_home_document($locale);$json=json_encode($doc,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$insert->execute([cms_page_uuid(),$activityId,$locale,'',$title,$nav,$json,$json,$now,$now,$now,$now]);}
}
function cms_pages(PDO $db,int $activityId,?string $locale=null,bool $includeArchived=false): array {
    $sql='SELECT * FROM cms_pages WHERE activity_id=?';$args=[$activityId];if($locale!==null){$sql.=' AND locale=?';$args[]=$locale;}if(!$includeArchived)$sql.=" AND status!='archived'";$sql.=' ORDER BY locale,sort_order,id';$q=$db->prepare($sql);$q->execute($args);return $q->fetchAll();
}
function cms_page_by_id(PDO $db,int $id): ?array {$q=$db->prepare('SELECT * FROM cms_pages WHERE id=?');$q->execute([$id]);return $q->fetch()?:null;}
function cms_page_by_uuid(PDO $db,string $uuid): ?array {$q=$db->prepare("SELECT * FROM cms_pages WHERE page_uuid=? AND status!='archived'");$q->execute([$uuid]);return $q->fetch()?:null;}
function cms_page_home(PDO $db,int $activityId,string $locale): ?array {$q=$db->prepare("SELECT * FROM cms_pages WHERE activity_id=? AND locale=? AND is_home=1 AND status!='archived' LIMIT 1");$q->execute([$activityId,$locale]);return $q->fetch()?:null;}
function cms_page_by_slug(PDO $db,int $activityId,string $locale,string $slug): ?array {$slug=cms_page_slug($slug);if($slug==='')return cms_page_home($db,$activityId,$locale);$q=$db->prepare("SELECT * FROM cms_pages WHERE activity_id=? AND locale=? AND slug=? AND status!='archived' LIMIT 1");$q->execute([$activityId,$locale,$slug]);return $q->fetch()?:null;}
function cms_page_doc(array $page,bool $published=true): array {$json=$published?($page['published_document_json']??null):($page['draft_document_json']??null);if(!$json)$json=$page['draft_document_json']??'{}';$doc=json_decode((string)$json,true);return cms_page_document(is_array($doc)?$doc:[]);}
function cms_page_unique_slug(PDO $db,int $activityId,string $locale,string $slug,?int $exceptId=null): string {$slug=cms_page_slug($slug);if($slug==='')$slug='pagina';$base=$slug;$n=2;while(true){$sql='SELECT id FROM cms_pages WHERE activity_id=? AND locale=? AND slug=? AND status!="archived"';$args=[$activityId,$locale,$slug];if($exceptId){$sql.=' AND id!=?';$args[]=$exceptId;}$q=$db->prepare($sql);$q->execute($args);if(!$q->fetchColumn())return $slug;$slug=$base.'-'.$n++;}}
function cms_page_create(PDO $db,int $activityId,string $locale,string $title,string $slug='',?int $copyId=null): array {
    $locale=normalize_public_locale($locale)??PUBLIC_LOCALE_EN;$copy=$copyId?cms_page_by_id($db,$copyId):null;$doc=$copy?cms_page_doc($copy,false):cms_page_document(['theme'=>'auto','meta'=>['title'=>$title,'description'=>''],'html'=>'<section class="section" data-cms-section="intro" data-cms-section-name="Nova seção"><p class="section-label" data-cms-editable>01 / Nova página</p><div class="statement-grid"><h2 data-cms-editable>'.h($title).'</h2><div class="statement-copy"><p data-cms-editable>Edite este conteúdo diretamente na página.</p></div></div></section>']);$slug=cms_page_unique_slug($db,$activityId,$locale,$slug?:$title);$json=json_encode($doc,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$now=utc_now();$q=$db->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM cms_pages WHERE activity_id=? AND locale=?');$q->execute([$activityId,$locale]);$order=(int)$q->fetchColumn();$insert=$db->prepare('INSERT INTO cms_pages(page_uuid,activity_id,locale,slug,title,nav_title,status,is_home,show_in_nav,sort_order,draft_document_json,published_document_json,draft_revision,published_revision,draft_updated_at,published_at,created_at,updated_at)VALUES(?,?,?,?,?,?,"active",0,1,?,?,NULL,1,NULL,?,NULL,?,?)');$insert->execute([cms_page_uuid(),$activityId,$locale,$slug,trim($title)?:'Nova página',trim($title)?:'Nova página',$order,$json,$now,$now,$now]);return cms_page_by_id($db,(int)$db->lastInsertId())??throw new RuntimeException('page_create_failed');
}
function cms_page_save(PDO $db,int $id,array $document,int $revision,array $settings=[]): array {
    $page=cms_page_by_id($db,$id)??throw new RuntimeException('page_not_found');$document=cms_page_document($document);$json=json_encode($document,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$locale=normalize_public_locale((string)($settings['locale']??$page['locale']))??$page['locale'];$slug=(int)$page['is_home']===1?'':cms_page_unique_slug($db,(int)$page['activity_id'],$locale,(string)($settings['slug']??$page['slug']),$id);$title=trim((string)($settings['title']??$page['title']))?:$page['title'];$nav=trim((string)($settings['nav_title']??$page['nav_title']))?:$title;$show=!empty($settings['show_in_nav'])?1:0;$new=$revision+1;$now=utc_now();$q=$db->prepare('UPDATE cms_pages SET locale=?,slug=?,title=?,nav_title=?,show_in_nav=?,draft_document_json=?,draft_revision=?,draft_updated_at=?,updated_at=? WHERE id=? AND draft_revision=?');$q->execute([$locale,$slug,$title,$nav,$show,$json,$new,$now,$now,$id,$revision]);if($q->rowCount()!==1)throw new RuntimeException('revision_conflict');return cms_page_by_id($db,$id)??throw new RuntimeException('page_not_found');
}
function cms_page_publish(PDO $db,int $id): array {$page=cms_page_by_id($db,$id)??throw new RuntimeException('page_not_found');$now=utc_now();$q=$db->prepare('UPDATE cms_pages SET published_document_json=draft_document_json,published_revision=draft_revision,published_at=?,updated_at=? WHERE id=?');$q->execute([$now,$now,$id]);return cms_page_by_id($db,$id)??throw new RuntimeException('page_not_found');}
function cms_page_set_home(PDO $db,int $id): array {$page=cms_page_by_id($db,$id)??throw new RuntimeException('page_not_found');$db->beginTransaction();try{$q=$db->prepare('UPDATE cms_pages SET is_home=0 WHERE activity_id=? AND locale=?');$q->execute([(int)$page['activity_id'],$page['locale']]);$q=$db->prepare("UPDATE cms_pages SET is_home=1,slug='',show_in_nav=1,updated_at=? WHERE id=?");$q->execute([utc_now(),$id]);$db->commit();return cms_page_by_id($db,$id)??throw new RuntimeException('page_not_found');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
function cms_page_archive(PDO $db,int $id): void {$page=cms_page_by_id($db,$id)??throw new RuntimeException('page_not_found');if((int)$page['is_home']===1)throw new RuntimeException('cannot_archive_home');$q=$db->prepare("UPDATE cms_pages SET status='archived',show_in_nav=0,updated_at=? WHERE id=?");$q->execute([utc_now(),$id]);}
function cms_nav_pages(PDO $db,int $activityId,string $locale): array {$q=$db->prepare("SELECT * FROM cms_pages WHERE activity_id=? AND locale=? AND status!='archived' AND show_in_nav=1 AND published_document_json IS NOT NULL ORDER BY sort_order,id");$q->execute([$activityId,$locale]);return $q->fetchAll();}
